<script setup lang="ts">import { computed, onMounted, ref } from 'vue'; import { api, request } from '../lib/api'; import { detectInstallPlatform, installInstructions, installPwa, isStandalone } from '../lib/pwa'; const boot=ref<any>(),installHelp=ref(''),showInstall=ref(false); const platform=computed(()=>typeof navigator==='undefined'?'other':detectInstallPlatform(navigator.userAgent,navigator.platform,navigator.maxTouchPoints)); onMounted(async()=>boot.value=await api('bootstrap')); async function logout(){await request('logout');location.href='/login?redirect-to=%2Finventory'} async function install(){if(!(await installPwa())){installHelp.value=installInstructions(platform.value);showInstall.value=true}}</script>
<template><section class="app-shell"><h1>更多</h1><RouterLink class="selection-row" to="/history">库存记录</RouterLink><RouterLink class="selection-row" to="/history?status=unfinished">草稿 <b v-if="boot?.unfinished_count">{{boot.unfinished_count}}</b></RouterLink><RouterLink class="selection-row" to="/pending">待处理（{{boot?.pending_count || 0}}）</RouterLink><button v-if="!isStandalone" class="selection-row" @click="install">安装到手机 / 电脑</button><p class="selection-row">当前账户：{{boot?.user}}</p><button class="danger-action" @click="logout">退出登录</button><div v-if="showInstall" class="modal" role="dialog" aria-modal="true"><section><h2>安装物资管理</h2><p>{{installHelp}}</p><button class="primary" @click="showInstall=false">知道了</button></section></div></section></template>
